// A second deployment origin length: same contract, WebAuthn origin length 28
// (e.g. https://evidence.example.org), generated by scripts/variant.mjs.
import { describe, expect, it } from "vitest";
import * as Unforged28 from "../managed/unforged28/contract/index.js";
import { fingerprint, Passkey, policy, Pool } from "./harness.js";

const RP = "evidence.example.org";
const ORIGIN = "https://evidence.example.org";
const pol = policy(RP, ORIGIN);

describe("deployment variant (28-byte origin)", () => {
  it("seals with a passkey bound to the hosted origin", async () => {
    const pool = await Pool.deploy({ module: Unforged28 as never });
    const keys = [new Passkey(), new Passkey()];
    for (const k of keys) await pool.enroll(Unforged28.pureCircuits.deviceCommitment(k.pk, k.salt, pol));
    const fp = fingerprint("hosted.jpg");
    await pool.seal(keys[0], fp, { policy: pol, overrides: { origin: ORIGIN, rpId: RP } });
    expect(pool.ledger.seals.member(fp)).toBe(true);
  });

  it("refuses an assertion made on localhost for a hosted-origin device", async () => {
    const pool = await Pool.deploy({ module: Unforged28 as never });
    const keys = [new Passkey(), new Passkey()];
    for (const k of keys) await pool.enroll(Unforged28.pureCircuits.deviceCommitment(k.pk, k.salt, pol));
    const fp = fingerprint("hosted-2.jpg");
    await expect(
      pool.seal(keys[0], fp, { policy: pol, overrides: { origin: "http://localhost:5173", rpId: RP } }),
    ).rejects.toThrow(/BAD_SIGNATURE/);
  });
});
